#include <vector>
#include <cstddef>
#include <cmath>
#include <algorithm>
#include <omp.h>

struct COOElement {
   size_t row, column;
   double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Use OpenMP to compute in parallel.
*/
void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    x.assign(N, 0.0);
    if (N == 0) return;

    // Build CSR from COO (safe and deterministic; then use parallel Gauss-Seidel via Jacobi).
    std::vector<size_t> rowPtr(N + 1, 0);
    for (const auto &e : A) {
        if (e.row < N && e.column < N) rowPtr[e.row + 1]++;
    }
    for (size_t i = 0; i < N; ++i) rowPtr[i + 1] += rowPtr[i];

    const size_t nnz = rowPtr[N];
    std::vector<size_t> colInd(nnz);
    std::vector<double>  vals(nnz);

    // Fill CSR; use per-row cursors to avoid races.
    std::vector<size_t> cursor = rowPtr;
    for (const auto &e : A) {
        if (e.row >= N || e.column >= N) continue;
        size_t pos = cursor[e.row]++;
        colInd[pos] = e.column;
        vals[pos]   = e.value;
    }

    // Sort each CSR row by column to make diagonal lookup stable.
    for (size_t r = 0; r < N; ++r) {
        size_t begin = rowPtr[r], end = rowPtr[r + 1];
        // simple insertion sort per row (rows are typically short); avoid extra allocations
        for (size_t i = begin + 1; i < end; ++i) {
            size_t c = colInd[i];
            double v = vals[i];
            size_t j = i;
            while (j > begin && colInd[j - 1] > c) {
                colInd[j] = colInd[j - 1];
                vals[j]   = vals[j - 1];
                --j;
            }
            colInd[j] = c;
            vals[j]   = v;
        }
    }

    // Precompute diagonal (including possible duplicates) and check for singular rows.
    std::vector<double> diag(N, 0.0);
    #pragma omp parallel for schedule(static)
    for (std::ptrdiff_t r = 0; r < static_cast<std::ptrdiff_t>(N); ++r) {
        double d = 0.0;
        for (size_t k = rowPtr[r]; k < rowPtr[r + 1]; ++k) {
            if (colInd[k] == static_cast<size_t>(r)) d += vals[k];
        }
        diag[r] = d;
    }

    // Jacobi iteration: x^{k+1} = (b - (A - D)x^k)/diag
    // Parallel-safe because each thread writes a distinct xNew[i].
    std::vector<double> xNew(N, 0.0);

    const int maxIters = 20000;
    const double tol = 1e-12;

    for (int it = 0; it < maxIters; ++it) {
        double maxDiff = 0.0;

        #pragma omp parallel
        {
            double localMax = 0.0;

            #pragma omp for schedule(static)
            for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(N); ++i) {
                const double di = diag[i];
                // If diagonal is zero, we cannot do a stable Jacobi update; keep value unchanged.
                if (di == 0.0) {
                    xNew[i] = x[i];
                    continue;
                }

                double sum = 0.0;
                for (size_t k = rowPtr[i]; k < rowPtr[i + 1]; ++k) {
                    const size_t j = colInd[k];
                    if (j == static_cast<size_t>(i)) continue;
                    sum += vals[k] * x[j];
                }
                const double xi = (b[i] - sum) / di;
                xNew[i] = xi;

                const double diff = std::fabs(xi - x[i]);
                if (diff > localMax) localMax = diff;
            }

            #pragma omp critical
            {
                if (localMax > maxDiff) maxDiff = localMax;
            }
        }

        x.swap(xNew);
        if (maxDiff < tol) break;
    }
}
